mapper.select:
SELECT 
FROM sys_role_menu

    AND tenant_id = #{tenantId}
    AND role_id = #{roleId}
    AND menu_id = #{menuId}

ORDER BY 1

mapper.delete:
DELETE FROM sys_role_menu

    AND tenant_id = #{tenantId}
    AND role_id = #{roleId}
    AND menu_id = #{menuId}

mapper.select:
SELECT DISTINCT rm.menu_id
FROM sys_role_menu rm
INNER JOIN sys_role r ON r.id = rm.role_id AND r.tenant_id = rm.tenant_id AND r.deleted = 0 AND r.status = '0'
WHERE rm.tenant_id = #{tenantId}
  AND rm.role_id IN #{roleId}

mapper.delete:
DELETE FROM sys_role_menu
WHERE tenant_id <> '0'
  AND menu_id IN #{menuId}
